# construct test output as vertical arrangement of the three matching solid blocks
bg=7
out=[[bg]*7 for _ in range(19)]
shapes={
 1:[[1,7,1],[1,7,1],[1,1,1]],
 4:[[4,7,7],[4,4,7],[4,7,4]],
 6:[[6,6,6],[7,6,7],[6,6,6]],
}
for top,col in [(1,1),(7,4),(13,6)]:
    for r in range(top,top+5):
        for c in range(1,6): out[r][c]=col
    for i in range(3):
        for j in range(3):
            if shapes[col][i][j] != bg:
                out[top+1+i][2+j]=bg
print('\n'.join(' '.join(map(str,row)) for row in out))
